// IEnumerable - filters in memory
IEnumerable<Product> products = GetProducts();
var expensive = products.Where(p => p.Price > 100);
// Query executes when enumerated, all data loaded first

// IQueryable - translates to SQL
IQueryable<Product> products = dbContext.Products;
var expensive = products.Where(p => p.Price > 100);
// Translates to: SELECT * FROM Products WHERE Price > 100
